contract InvMutTest {
  C c;

  constructor(C _c) { c = _c; }

  function test() public {
    // Requires this contract to be the current owner of c, so owned() passes onlyOwner.
    require(c.owner() == address(this));
    c.owned();
    // In P, owned() sets owner back to msg.sender; in M it is set to address(0).
    assert(c.owner() == address(this));
  }

  receive() external payable {}
  fallback() external payable {}
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }

  function test(uint256 b) public {
    require(b > 0);
    uint256 supplyBefore = c.totalSupply();
    c.burn(b);
    assert(c.totalSupply() == supplyBefore - b);
  }
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function f(uint256 amount) public {
    require(amount > 0 && amount <= c.totalSupply());
    uint256 before = c.totalSupply();
    c.burn(amount);
    assert(c.totalSupply() == before - amount);
  }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function runBurn(uint256 v) public {
        // This test contract must be the owner so that burn is reachable.
        require(c.owner() == address(this));
        // The amount exceeds our own balance but is covered by totalSupply.
        require(c.balanceOf(address(this)) < v);
        require(v <= c.totalSupply());

        bool reverted;
        try c.burn(v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Burning more than the caller's balance must always revert.
        assert(reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function testNonOwnerBurnReverts(uint256 amount) public {
        bool reverted = false;
        try c.burn(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }

  function run(uint256 amt) public {
    require(amt > 0);
    require(c.owner() != address(this)); // caller is not the owner
    uint256 supplyBefore = c.totalSupply();
    bool ok = false;
    try c.burn(amt) { ok = true; } catch { ok = false; }
    assert(!ok && c.totalSupply() == supplyBefore);
  }

  receive() external payable {}
  fallback() external payable {}
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }

  function testBurnNonOwner(uint256 v) public {
    require(c.balanceOf(address(this)) >= v);
    (bool ok, ) = address(c).call(abi.encodeWithSelector(c.burn.selector, v));
    assert(!ok);
  }

  receive() external payable {}
  fallback() external payable {}
}
